{"command":"cat <<'EOF' > bartib_core.py
import re
from datetime import datetime, timedelta

def parse_time(s):
    try:
        return datetime.strptime(s, "%Y-%m-%d %H:%M")
    except ValueError:
        return None

class Activity:
    def __init__(self, start_time, end_time, project, description, line_num):
        self.start_time = start_time
        self.end_time = end_time
        self.project = project
        self.description = description
        self.line_num = line_num

    def is_running(self):
        return self.end_time is None

    def duration(self):
        end = self.end_time or datetime.now().replace(second=0, microsecond=0)
        return end - self.start_time

def format_duration(td):
    mins = int(td.total_seconds() // 60)
    if mins < 1:
        return "<1m"
    elif mins < 60:
        return f"{mins:02d}m"
    else:
        h = mins // 60
        m = mins % 60
        return f"{h}h {m:02d}m"

def load_file(filepath):
    activities = []
    errors = []
    try:
        with open(filepath, 'r') as f:
            for i, line in enumerate(f):
                line = line.strip()
                if not line:
                    continue
                parts = line.split(' | ')
                if len(parts) != 3:
                    errors.append((i+1, line))
                    continue
                times_str, proj, desc = parts
                time_parts = times_str.split(' - ')
                start = parse_time(time_parts[0])
                if not start:
                    errors.append((i+1, line))
                    continue
                end = None
                if len(time_parts) > 1:
                    end = parse_time(time_parts[1])
                    if not end:
                        errors.append((i+1, line))
                        continue
                activities.append(Activity(start, end, proj, desc, i+1))
    except Exception as e:
        pass
    return activities, errors

