#!/usr/bin/env python3
import sys, os, re, datetime
from datetime import timedelta

# Import help strings previously dumped
from help_strings import HELP_STRINGS

def parse_time_arg(s):
    m = re.match(r'^(\d{2}):(\d{2})$', s)
    if not m: return None
    h, mins = int(m.group(1)), int(m.group(2))
    if h > 23 or mins > 59: return None
    return datetime.datetime.now().replace(hour=h, minute=mins, second=0, microsecond=0)

def parse_date(s):
    try: return datetime.datetime.strptime(s, "%Y-%m-%d %H:%M")
    except: return None

class Activity:
    def __init__(self, start_time, end_time, project, description, line_num):
        self.start_time = start_time
        self.end_time = end_time
        self.project = project
        self.description = description
        self.line_num = line_num

    def duration(self, round_mins=None):
        end = self.end_time or datetime.datetime.now().replace(second=0, microsecond=0)
        dur = end - self.start_time
        return dur

def format_duration(td):
    mins = int(td.total_seconds() // 60)
    if mins < 1: return "<1m"
    if mins < 60: return f"{mins:02d}m"
    return f"{mins//60}h {mins%60:02d}m"

def load_file(path):
    acts, errs = [], []
    if not os.path.exists(path):
        return acts, errs
    try:
        with open(path, 'r') as f:
            for i, line in enumerate(f):
                line = line.strip()
                if not line: continue
                parts = line.split(' | ')
                if len(parts) != 3: errs.append((i+1, line)); continue
                start = parse_date(parts[0].split(' - ')[0])
                if not start: errs.append((i+1, line)); continue
                end = parse_date(parts[0].split(' - ')[1]) if ' - ' in parts[0] else None
                acts.append(Activity(start, end, parts[1], parts[2], i+1))
    except Exception as e:
        print(f"Error: Could not read from file: {path}\n\nCaused by:\n    {e}")
        sys.exit(1)
    return acts, errs

def save_file(path, acts):
    with open(path, 'w') as f:
        for a in acts:
            s = a.start_time.strftime("%Y-%m-%d %H:%M")
            e = f" - {a.end_time.strftime('%Y-%m-%d %H:%M')}" if a.end_time else ""
            f.write(f"{s}{e} | {a.project} | {a.description}\n")

def get_file():
