def parse_time_arg(s):
    m = re.match(r'^(\d{2}):(\d{2})$', s)
    if not m: return None
    h, mins = int(m.group(1)), int(m.group(2))
    if h > 23 or mins > 59: return None
    return datetime.datetime.now().replace(hour=h, minute=mins, second=0, microsecond=0)

def parse_date(s):
    try: return datetime.datetime.strptime(s, "%Y-%m-%d %H:%M")
    except: return None

class Activity:
    def __init__(self, start_time, end_time, project, description, line_num):
        self.start_time = start_time
        self.end_time = end_time
        self.project = project
        self.description = description
        self.line_num = line_num

    def duration(self, round_mins=None):
        end = self.end_time or datetime.datetime.now().replace(second=0, microsecond=0)
        dur = end - self.start_time
        return dur

def format_duration(td):
    mins = int(td.total_seconds() // 60)
    if mins < 1: return "<1m"
    if mins < 60: return f"{mins:02d}m"
    return f"{mins//60}h {mins%60:02d}m"

def load_file(path):
    acts, errs = [], []
    if not os.path.exists(path): return acts, errs
    try:
        with open(path, 'r') as f:
            for i, line in enumerate(f):
                line = line.strip()
                if not line: continue
                parts = line.split(' | ')
                if len(parts) != 3: errs.append((i+1, line)); continue
                start = parse_date(parts[0].split(' - ')[0])
                if not start: errs.append((i+1, line)); continue
                end = parse_date(parts[0].split(' - ')[1]) if ' - ' in parts[0] else None
                acts.append(Activity(start, end, parts[1], parts[2], i+1))
    except Exception as e:
        print(f"Error: Could not read from file: {path}\n\nCaused by:\n    {e}")
        sys.exit(1)
    return acts, errs

def save_file(path, acts):
    with open(path, 'w') as f:
        for a in acts:
            s = a.start_time.strftime("%Y-%m-%d %H:%M")
            e = f" - {a.end_time.strftime('%Y-%m-%d %H:%M')}" if a.end_time else ""
            f.write(f"{s}{e} | {a.project} | {a.description}\n")

def get_file():
    opts, *_ = parse_args(sys.argv[1:])
    f = opts.get('file') or os.environ.get('BARTIB_FILE')
    if not f:
        print("Error: Please specify a file with your activity log either as -f option or as BARTIB_FILE environment variable")
        sys.exit(1)
    return f

def parse_args(args):
    flags, opts, cmd, cmd_args = {}, {}, None, []
    i = 0
    while i < len(args):
        a = args[i]
        if cmd is None:
            if a in ('-h', '--help'): flags['help'] = True; i += 1
            elif a in ('-V', '--version'): flags['version'] = True; i += 1
            elif a == '-f': opts['file'] = args[i+1]; i += 2
            elif not a.startswith('-'): cmd = a; i += 1
            else:
                print(f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable [OPTIONS] <SUBCOMMAND>\n\nFor more information try --help")
                sys.exit(1)
        else:
            cmd_args.append(a)
            i += 1
    return opts, flags, cmd, cmd_args

def parse_sub_args(args, subcmd, req=None, options=None, flags=None):
    parsed_opts, parsed_flags = {}, {}
    i = 0
    while i < len(args):
        a = args[i]
        if a in ('-h', '--help'):
            print(HELP_STRINGS.get(subcmd, ""))
            sys.exit(0)
        elif options and a in options:
            parsed_opts[options[a]] = args[i+1]; i += 2
        elif flags and a in flags:
            parsed_flags[flags[a]] = True; i += 1
        elif not a.startswith('-') and subcmd in ('continue', 'search') and i == len(args)-1 and 'pos' not in parsed_opts:
            parsed_opts['pos'] = a; i += 1
        else:
            usage = HELP_STRINGS.get(subcmd, "").split("USAGE:\n")[1].split("\n\n")[0].strip()
            print(f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {usage}\n\nFor more information try --help")
            sys.exit(1)
    if req:
        missing = [r for r in req if r not in parsed_opts]
        if missing:
            m_str = "\n".join(f"    --{r} <{r.upper()}>" for r in missing)
            usage = HELP_STRINGS.get(subcmd, "").split("USAGE:\n")[1].split("\n\n")[0].strip()
            print(f"error: The following required arguments were not provided:\n{m_str}\n\nUSAGE:\n    {usage}\n\nFor more information try --help")
            sys.exit(1)
    return parsed_opts, parsed_flags

def run_start(file, opts):
    acts, errs = load_file(file)
    now = datetime.datetime.now().replace(second=0, microsecond=0)
    t = now
    if opts.get('t'):
        pt = parse_time_arg(opts['t'])
        if pt: t = pt
        else: print(f'Can not parse "{opts["t"]}" as time. Argument for -t/--time is ignored (input contains invalid characters)')

    for a in acts:
        if not a.end_time:
            a.end_time = t
            print(f'Stopped activity: "{a.description}" ({a.project}) started at {a.start_time.strftime("%Y-%m-%d %H:%M")} ({format_duration(a.duration())})')

    acts.append(Activity(t, None, opts['p'], opts['d'], len(acts)+1))
    print(f'Started activity: "{opts["d"]}" ({opts["p"]}) at {t.strftime("%Y-%m-%d %H:%M")}')
    save_file(file, acts)

def run_stop(file, opts):
    acts, errs = load_file(file)
    now = datetime.datetime.now().replace(second=0, microsecond=0)
    t = now
    if opts.get('t'):
        pt = parse_time_arg(opts['t'])
        if pt: t = pt
        else: print(f'Can not parse "{opts["t"]}" as time. Argument for -t/--time is ignored (input contains invalid characters)')

    changed = False
    for a in acts:
        if not a.end_time:
            a.end_time = t
            changed = True
            print(f'Stopped activity: "{a.description}" ({a.project}) started at {a.start_time.strftime("%Y-%m-%d %H:%M")} ({format_duration(a.duration())})')
    if changed: save_file(file, acts)

def run_cancel(file):
    acts, errs = load_file(file)
    to_keep = []
    changed = False
    for a in acts:
        if not a.end_time:
            changed = True
            print(f'Canceled activity: "{a.description}" ({a.project}) started at {a.start_time.strftime("%Y-%m-%d %H:%M")}')
        else:
            to_keep.append(a)
    if changed: save_file(file, to_keep)

def run_change(file, opts):
    acts, errs = load_file(file)
    changed = False
    for a in acts:
        if not a.end_time:
            if opts.get('d'): a.description = opts['d']
            if opts.get('p'): a.project = opts['p']
            if opts.get('t'):
                pt = parse_time_arg(opts['t'])
                if pt: a.start_time = pt
            changed = True
            print(f'Changed activity: "{a.description}" ({a.project}) started at {a.start_time.strftime("%Y-%m-%d %H:%M")}')
    if changed: save_file(file, acts)

def run_continue(file, opts):
    acts, errs = load_file(file)
    idx = int(opts.get('pos', 0))
    if idx < 0 or idx >= len(acts): return
    target = acts[-1 - idx]
    d = opts.get('d', target.description)
    p = opts.get('p', target.project)

    now = datetime.datetime.now().replace(second=0, microsecond=0)
    t = now
    if opts.get('t'):
        pt = parse_time_arg(opts['t'])
        if pt: t = pt

    for a in acts:
        if not a.end_time:
            a.end_time = t
            print(f'Stopped activity: "{a.description}" ({a.project}) started at {a.start_time.strftime("%Y-%m-%d %H:%M")} ({format_duration(a.duration())})')

    acts.append(Activity(t, None, p, d, len(acts)+1))
    print(f'Started activity: "{d}" ({p}) at {t.strftime("%Y-%m-%d %H:%M")}')
    save_file(file, acts)

def pad(s, w):
    return s + '\xa0' * (w - len(s))

def filter_acts(acts, opts, flags):
    now = datetime.datetime.now()
    filtered = []

    d_flag = opts.get('date') or opts.get('d')
    from_flag = opts.get('from')
    to_flag = opts.get('to')
    proj_flag = opts.get('project') or opts.get('p')

    for a in acts:
        if proj_flag and a.project != proj_flag: continue

        ok = True
        if flags.get('today'):
            if a.start_time.date() != now.date(): ok = False
        elif flags.get('yesterday'):
            if a.start_time.date() != (now - datetime.timedelta(days=1)).date(): ok = False
        elif flags.get('current_week'):
            if a.start_time.isocalendar()[1] != now.isocalendar()[1]: ok = False
        elif flags.get('last_week'):
            if a.start_time.isocalendar()[1] != (now - datetime.timedelta(days=7)).isocalendar()[1]: ok = False

        if d_flag:
            try:
                dt = datetime.datetime.strptime(d_flag, "%Y-%m-%d")
                if a.start_time.date() != dt.date(): ok = False
            except: pass

        if from_flag:
            try:
                dt = datetime.datetime.strptime(from_flag, "%Y-%m-%d")
                if a.start_time.date() < dt.date(): ok = False
            except: pass

        if to_flag:
            try:
                dt = datetime.datetime.strptime(to_flag, "%Y-%m-%d")
                if a.start_time.date() > dt.date(): ok = False
            except: pass

        if ok: filtered.append(a)
    return filtered

def run_list(file, opts, flags):
    acts, errs = load_file(file)
    acts = filter_acts(acts, opts, flags)

    groups = {}
    for a in acts:
        date_str = a.start_time.strftime("%Y-%m-%d")
        if date_str not in groups: groups[date_str] = []
        groups[date_str].append(a)

    print()
    max_d, max_p, max_dur = 11, 7, 8
    for a in acts:
        max_d = max(max_d, len(a.description))
        max_p = max(max_p, len(a.project))
        max_dur = max(max_dur, len(format_duration(a.duration())))

    print(f"\x1b[4mStarted\x1b[0m \x1b[4mStopped\x1b[0m \x1b[4m{pad('Description', max_d)}\x1b[0m \x1b[4m{pad('Project', max_p)}\x1b[0m \x1b[4m{pad('Duration', max_dur)}\x1b[0m \n")

    for date, g_acts in groups.items():
        total = sum((a.duration().total_seconds() for a in g_acts), 0)
        total_td = timedelta(seconds=total)
        print(f"\x1b[1m{date}\t{format_duration(total_td)}\x1b[0m")
        for a in g_acts:
            st = a.start_time.strftime("%H:%M")
            et = a.end_time.strftime("%H:%M") if a.end_time else "-"
            d = a.description
            p = a.project
            dur = format_duration(a.duration())
            if not a.end_time:
                print(f"\x1b[32m{pad(st, 7)}\x1b[0m \x1b[32m{pad(et, 7)}\x1b[0m \x1b[32m{pad(d, max_d)}\x1b[0m \x1b[32m{pad(p, max_p)}\x1b[0m \x1b[32m{pad(dur, max_dur)}\x1b[0m ")
            else:
                print(f"{pad(st, 7)} {pad(et, 7)} {pad(d, max_d)} {pad(p, max_p)} {pad(dur, max_dur)} ")
        print()

def run_report(file, opts, flags):
    acts, errs = load_file(file)
    acts = filter_acts(acts, opts, flags)

    projects = {}
    for a in acts:
        if a.project not in projects: projects[a.project] = {}
        if a.description not in projects[a.project]: projects[a.project][a.description] = 0
        projects[a.project][a.description] += a.duration().total_seconds()

    print()
    total_all = 0
    max_w = 5
    for p, tasks in projects.items():
        max_w = max(max_w, len(p))
        for t in tasks:
            max_w = max(max_w, len(t) + 4)

    for p, tasks in sorted(projects.items()):
        p_tot = sum(tasks.values())
        total_all += p_tot
        pad_p = "." * max(0, max_w - len(p))
        print(f"\x1b[1m{p}{pad_p} {format_duration(timedelta(seconds=p_tot))}\x1b[0m")
        for t, dur in sorted(tasks.items()):
            pad_t = "." * max(0, max_w - (len(t) + 4))
            print(f"    {t}{pad_t} {format_duration(timedelta(seconds=dur))}")
        print()

    pad_tot = "." * max(0, max_w - 5)
    print(f"\x1b[1mTotal{pad_tot} {format_duration(timedelta(seconds=total_all))}\x1b[0m\n")

def run_status(file, opts):
    acts, errs = load_file(file)
    if opts.get('p'):
        acts = [a for a in acts if a.project == opts['p']]
    running = [a for a in acts if not a.end_time]
    now_act = running[0] if running else None

    now = datetime.datetime.now()
    today_acts = [a for a in acts if a.start_time.date() == now.date()]
    today_dur = sum((a.duration().total_seconds() for a in today_acts), 0)

    week_dur = sum((a.duration().total_seconds() for a in acts if a.start_time.isocalendar()[1] == now.isocalendar()[1]), 0)
    month_dur = sum((a.duration().total_seconds() for a in acts if a.start_time.month == now.month and a.start_time.year == now.year), 0)

    if opts.get('p'):
        print(f"\x1b[2m\n =======\x1b[0m\x1b[3m Status for project: \x1b[0m\x1b[1m{opts['p']}\x1b[0m\x1b[2m ======= \n\x1b[0m", end="")
    else:
        print(f"\x1b[2m\n =======\x1b[0m\x1b[3m Status for \x1b[0m\x1b[1mALL\x1b[0m\x1b[3m projects \x1b[0m\x1b[2m ======= \n\x1b[0m", end="")

    if now_act:
        print(f"\x1b[2;3m\n  NOW: \x1b[0m\x1b[1;32m{now_act.description}\x1b[0m\x1b[2;3m on \x1b[0m\x1b[3m{now_act.project}\x1b[0m\x1b[2m ...... \x1b[0m\x1b[1m{format_duration(now_act.duration())}\x1b[0m\x1b[2m\n\n\x1b[0m", end="")
    else:
        print(f"\x1b[2;3m\n  NOW: \x1b[0m\x1b[1m NO Activity\n\n\x1b[0m", end="")

    print(f"\x1b[3m \x1b[0m\x1b[2;3m Today......................... \x1b[0m\x1b[1m{format_duration(timedelta(seconds=today_dur))}\x1b[0m\x1b[3m\n\x1b[0m", end="")
    print(f"\x1b[3m \x1b[0m\x1b[2;3m Current week.................. \x1b[0m\x1b[1m{format_duration(timedelta(seconds=week_dur))}\x1b[0m\x1b[3m\n\x1b[0m", end="")
    print(f"\x1b[3m \x1b[0m\x1b[2;3m Current month................. \x1b[0m\x1b[1m{format_duration(timedelta(seconds=month_dur))}\x1b[0m\x1b[3m\n\x1b[0m")

def run_projects(file, flags):
    acts, errs = load_file(file)
    projs = sorted(list(set(a.project for a in acts)))
    for p in projs:
        print(f'"{p}"')

def run_last_or_search(file, opts, subcmd):
    acts, errs = load_file(file)
    seen = set()
    unique = []
    term = opts.get('pos') if subcmd == 'search' else None

    for i in range(len(acts)-1, -1, -1):
        a = acts[i]
        k = (a.description, a.project)
        if k not in seen:
            if term and term not in a.description and term not in a.project: continue
            seen.add(k)
            unique.append((len(acts)-1-i, a))

    unique.reverse()
    if subcmd == 'last':
        n = int(opts.get('n', 10))
        unique = unique[-n:]

    if not unique: return

    print()
    max_d = max(11, max(len(a.description) for _, a in unique))
    max_p = max(7, max(len(a.project) for _, a in unique))
    pad_h = " " if subcmd == 'last' else "  "
    print(f"\x1b[4m #{pad_h}\x1b[0m \x1b[4m{pad('Description', max_d)}\x1b[0m \x1b[4m{pad('Project', max_p)}\x1b[0m ")

    for idx, a in unique:
        idx_str = f"[{idx}]"
        pad_idx = 4 if subcmd == 'search' else 3
        print(f"{pad(idx_str, pad_idx)} {pad(a.description, max_d)} {pad(a.project, max_p)} ")
    print()

def main():
    opts, flags, cmd, cmd_args = parse_args(sys.argv[1:])
    if flags.get('help'):
        print(HELP_STRINGS.get("", ""))
        sys.exit(0)
    if flags.get('version'):
        print("bartib 1.1.0")
        sys.exit(0)

    if not cmd:
        print(HELP_STRINGS.get("", ""), file=sys.stderr)
        sys.exit(1)

    if cmd == 'start':
        options = {'-d': 'd', '--description': 'd', '-p': 'p', '--project': 'p', '-t': 't', '--time': 't'}
        sub_opts, _ = parse_sub_args(cmd_args, cmd, ['d', 'p'], options)
        run_start(get_file(), sub_opts)
    elif cmd == 'stop':
        options = {'-t': 't', '--time': 't'}
        sub_opts, _ = parse_sub_args(cmd_args, cmd, [], options)
        run_stop(get_file(), sub_opts)
    elif cmd == 'cancel':
        run_cancel(get_file())
    elif cmd == 'change':
        options = {'-d': 'd', '--description': 'd', '-p': 'p', '--project': 'p', '-t': 't', '--time': 't'}
        sub_opts, _ = parse_sub_args(cmd_args, cmd, [], options)
        run_change(get_file(), sub_opts)
    elif cmd == 'continue':
        options = {'-d': 'd', '--description': 'd', '-p': 'p', '--project': 'p', '-t': 't', '--time': 't'}
        sub_opts, _ = parse_sub_args(cmd_args, cmd, [], options)
        run_continue(get_file(), sub_opts)
    elif cmd == 'list':
        options = {'-d': 'date', '--date': 'date', '-n': 'number', '--number': 'number', '-p': 'project', '--project': 'project', '--from': 'from', '--to': 'to'}
        flgs = {'--today': 'today', '--yesterday': 'yesterday', '--current_week': 'current_week', '--last_week': 'last_week', '--no_grouping': 'no_grouping'}
        sub_opts, sub_flags = parse_sub_args(cmd_args, cmd, [], options, flgs)
        run_list(get_file(), sub_opts, sub_flags)
    elif cmd == 'report':
        options = {'-d': 'date', '--date': 'date', '-p': 'project', '--project': 'project', '--from': 'from', '--to': 'to'}
        flgs = {'--today': 'today', '--yesterday': 'yesterday', '--current_week': 'current_week', '--last_week': 'last_week'}
        sub_opts, sub_flags = parse_sub_args(cmd_args, cmd, [], options, flgs)
        run_report(get_file(), sub_opts, sub_flags)
    elif cmd == 'status':
        options = {'-p': 'p', '--project': 'p'}
        sub_opts, sub_flags = parse_sub_args(cmd_args, cmd, [], options)
        run_status(get_file(), sub_opts)
    elif cmd == 'last':
        options = {'-n': 'n', '--number': 'n'}
        sub_opts, _ = parse_sub_args(cmd_args, cmd, [], options)
        run_last_or_search(get_file(), sub_opts, 'last')
    elif cmd == 'search':
        sub_opts, _ = parse_sub_args(cmd_args, cmd)
        run_last_or_search(get_file(), sub_opts, 'search')
    elif cmd == 'projects':
        sub_opts, sub_flags = parse_sub_args(cmd_args, cmd)
        run_projects(get_file(), sub_flags)
    elif cmd == 'edit':
        options = {'-e': 'e'}
        sub_opts, _ = parse_sub_args(cmd_args, cmd, [], options)
        editor = sub_opts.get('e') or os.environ.get('EDITOR')
        if not editor:
            print("Error: editor command is missing")
            sys.exit(1)
        os.system(f"{editor} {get_file()}")
    elif cmd == 'check':
        acts, errs = load_file(get_file())
        if not errs: print("All lines in the file have been successfully parsed as activities.")
        else:
            print(f"Found {len(errs)} line(s) with parsing errors\n")
            for i, line in errs: print(f"{line}\n  -> could not parse activity (Line: {i})")
    elif cmd == 'sanity':
        acts, _ = load_file(get_file())
        for a in acts:
            if a.end_time and a.end_time < a.start_time:
                print("Activity has negative duration")
                print(f"{a.description} (Started: {a.start_time.strftime('%Y-%m-%d %H:%M')}, Ended: {a.end_time.strftime('%Y-%m-%d %H:%M')}, Line: {a.line_num})\n")
    elif cmd == 'current':
        acts, _ = load_file(get_file())
        running = [a for a in acts if not a.end_time]
        print()
        if not running: return
        max_d = max(11, max(len(a.description) for a in running))
        max_p = max(7, max(len(a.project) for a in running))
        print(f"\x1b[4mStarted At{pad('', 6)}\x1b[0m \x1b[4m{pad('Description', max_d)}\x1b[0m \x1b[4m{pad('Project', max_p)}\x1b[0m \x1b[4mDuration\x1b[0m ")
        for a in running:
            st = a.start_time.strftime("%Y-%m-%d %H:%M")
            print(f"{st} {pad(a.description, max_d)} {pad(a.project, max_p)} {pad(format_duration(a.duration()), 8)} ")
        print()

if __name__ == '__main__':
    main()
